/** Email newsletter double opt-in and current email-channel suppression, owned by Experience. */
public final class NewsletterService {
 @FunctionalInterface public interface AntiSpamVerifier {boolean verify(String token,String idempotencyKey);}
 public record Request(String email,String policyVersion,String antiSpamToken){@Override public String toString(){return "NewsletterRequest[protected]";}}
 public record Accepted(boolean accepted){}
 public record Confirmation(boolean confirmed){}
 public record Unsubscribed(boolean unsubscribed){}
 public record Consent(String channel,String purpose,boolean granted,Instant recordedAt){}
 public record Context(String email,String confirmationLink,String unsubscribeLink,String classification){@Override public String toString(){return "NewsletterContext[protected]";}}
 public record SetConsentInput(UUID destinationId,String channel,String purpose,boolean granted,String policyVersion){}
 private static final Pattern EMAIL=Pattern.compile("(?i)^[A-Z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$");
 private final JdbcTemplate jdbc;private final PlatformStore store;private final AuditWriter audit;private final ConsentSecrets secrets;private final TransactionTemplate tx;private final Clock clock;private final String policyVersion,publicBase;private final Set<String> approvedPolicies;private final AntiSpamVerifier antiSpam;
 public NewsletterService(JdbcTemplate jdbc,PlatformStore store,AuditWriter audit,ConsentSecrets secrets,PlatformTransactionManager manager,Clock clock,String policyVersion,Set<String> approvedPolicies,String publicBase,AntiSpamVerifier antiSpam){this.jdbc=jdbc;this.store=store;this.audit=audit;this.secrets=secrets;this.tx=new TransactionTemplate(manager);this.tx.setTimeout(4);this.clock=clock;this.policyVersion=policyVersion;this.approvedPolicies=Set.copyOf(approvedPolicies);this.publicBase=publicBase;this.antiSpam=antiSpam;}
 private static Timestamp stamp(Instant value){return Timestamp.from(value);}
 private void lock(String key){jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"consent:"+key);}
 private void event(String type,UUID id,long version,UUID correlation,Object payload){var value=EventCodec.JSON.createObjectNode();value.put("event_id",EventCodec.uuid7(clock.instant()).toString());value.put("event_type",type);value.put("schema_version",1);value.put("producer","experience");value.put("occurred_at",clock.instant().toString());value.put("aggregate_id",id.toString());value.put("aggregate_version",version);value.putNull("organization_id");value.put("correlation_id",correlation.toString());value.putNull("traceparent");value.set("payload",EventCodec.JSON.valueToTree(payload));store.append(EventCodec.JSON.writeValueAsString(value),"newsletter-consent");}
 private void audit(String subject,UUID id,UUID correlation,String state,String channel){audit.append(subject,subject.startsWith("public:")?AuditValues.ActorKind.SYSTEM:AuditValues.ActorKind.USER,AuditValues.Action.CONSENT_CHANGE,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.SECURITY_POLICY,null,Map.of("state",state,"channel",channel),null);}
 private void consentEvent(UUID id,UUID party,String emailHash,String channel,String purpose,boolean granted,String policy,String source){Instant now=clock.instant();jdbc.update("INSERT INTO experience.consent_event(id,created_by,party_id,email_hash,channel,purpose,granted,policy_version,source,occurred_at,destination_hash,destination_kind,hash_key_version) VALUES (?,?,?,?,?,?,?,?,?,?,?,'EMAIL',?)",EventCodec.uuid7(now),party==null?"public:newsletter":party.toString(),party,emailHash,"EMAIL",purpose,granted,policy,source,stamp(now),emailHash,secrets.hashVersion());}
 private void consentChanged(UUID id,UUID party,String hash,String purpose,boolean granted,long revision,UUID correlation){var payload=new LinkedHashMap<String,Object>();payload.put("party_id",party);payload.put("destination_hash",hash);payload.put("destination_kind","EMAIL");payload.put("email_hash",hash);payload.put("channel","EMAIL");payload.put("purpose",purpose);payload.put("granted",granted);payload.put("revision",revision);event("consent.changed.v1",id,revision,correlation,payload);}
 private void pendingContext(UUID id,String confirmation,String unsubscribe,UUID job,String policy){var json=EventCodec.JSON.createObjectNode();if(job==null)json.putNull("jobId");else json.put("jobId",job.toString());json.put("confirmationToken",confirmation);json.put("unsubscribeToken",unsubscribe);json.put("policyVersion",policy);jdbc.update("UPDATE experience.newsletter_subscription SET confirmation_token_hash=?,confirmation_expires_at=?,unsubscribe_token_hash=?,encrypted_confirmation_context=?,confirmation_context_expires_at=?,version=version+1,updated_at=?,updated_by='newsletter-intake' WHERE id=?",secrets.capabilityHash("NEWSLETTER_CONFIRM",confirmation),stamp(clock.instant().plus(Duration.ofHours(24))),secrets.capabilityHash("NEWSLETTER_UNSUBSCRIBE",unsubscribe),secrets.encrypt(id,"CONFIRMATION_CONTEXT",EventCodec.JSON.writeValueAsString(json)),stamp(clock.instant().plus(Duration.ofHours(24))),stamp(clock.instant()),id);}
 public Accepted subscribe(Request input,String key,UUID correlation){readyIntake();key=ApiValues.idempotencyKey(key);if(input==null||input.email()==null||input.email().length()>254||!EMAIL.matcher(input.email()).matches()||input.policyVersion()==null||!input.policyVersion().equals(policyVersion)||input.antiSpamToken()==null||input.antiSpamToken().length()>512||!antiSpam.verify(input.antiSpamToken(),key))throw PhoneValues.denied();String email=input.email().strip().toLowerCase(Locale.ROOT),hash=secrets.emailHash(email);var request=EventCodec.JSON.valueToTree(Map.of("emailHash",hash,"policyVersion",input.policyVersion()));var result=store.executeLocal("public:newsletter","API-099",key,request,db->{lock("email:"+hash);var found=db.queryForList("SELECT * FROM experience.newsletter_subscription WHERE email_hash=? FOR UPDATE",hash);UUID id;long version;boolean issue=false;
  if(found.isEmpty()){id=EventCodec.uuid7(clock.instant());version=0;db.update("INSERT INTO experience.newsletter_subscription(id,created_by,updated_by,email_ciphertext,email_hash,state,unsubscribe_token_hash) VALUES (?,'public:newsletter','public:newsletter',?,?,'PENDING',?)",id,secrets.encrypt(id,"EMAIL",email),hash,secrets.capabilityHash("NEWSLETTER_UNSUBSCRIBE",secrets.token()));issue=true;}
  else{var row=found.getFirst();id=(UUID)row.get("id");version=((Number)row.get("version")).longValue();String state=(String)row.get("state");Timestamp expiry=(Timestamp)row.get("confirmation_expires_at");if(state.equals("ACTIVE"))return new PlatformStore.Response(202,EventCodec.JSON.valueToTree(new Accepted(true)),id);if(state.equals("PENDING")&&expiry!=null&&expiry.toInstant().isAfter(clock.instant()))return new PlatformStore.Response(202,EventCodec.JSON.valueToTree(new Accepted(true)),id);db.update("UPDATE experience.newsletter_subscription SET state='PENDING',party_id=NULL,verified_at=NULL,version=version+1,updated_at=?,updated_by='newsletter-intake' WHERE id=?",stamp(clock.instant()),id);version++;issue=true;}
  if(issue){String confirmation=secrets.token(),unsubscribe=secrets.token();pendingContext(id,confirmation,unsubscribe,null,input.policyVersion());long revision=version+1;event("newsletter.verification.requested.v1",id,revision,correlation,Map.of("subscription_id",id));audit("public:newsletter",id,correlation,"PENDING","EMAIL");}
  return new PlatformStore.Response(202,EventCodec.JSON.valueToTree(new Accepted(true)),id);
 });return EventCodec.JSON.treeToValue(result.body(),Accepted.class);}
 public Confirmation confirm(String token,String key,UUID correlation){readyCrypto();key=ApiValues.idempotencyKey(key);String hash=tokenHash("NEWSLETTER_CONFIRM",token);var req=EventCodec.JSON.valueToTree(Map.of("tokenHash",hash));var response=store.executeLocal("public:newsletter","API-100",key,req,db->{var found=db.queryForList("SELECT id,email_hash FROM experience.newsletter_subscription WHERE confirmation_token_hash=?",hash);if(found.size()!=1)return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Confirmation(false)),null);var first=found.getFirst();UUID id=(UUID)first.get("id");String emailHash=(String)first.get("email_hash");lock("email:"+emailHash);var rows=db.queryForList("SELECT id,email_hash,state,confirmation_expires_at,encrypted_confirmation_context,version FROM experience.newsletter_subscription WHERE id=? AND confirmation_token_hash=? FOR UPDATE",id,hash);if(rows.size()!=1)return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Confirmation(false)),id);var row=rows.getFirst();Timestamp expiry=(Timestamp)row.get("confirmation_expires_at");if(!"PENDING".equals(row.get("state"))||expiry==null||!expiry.toInstant().isAfter(clock.instant())||row.get("encrypted_confirmation_context")==null)return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Confirmation(false)),id);JsonNode context=EventCodec.JSON.readTree(secrets.decrypt(id,"CONFIRMATION_CONTEXT",(byte[])row.get("encrypted_confirmation_context")));String acceptedPolicy=context.path("policyVersion").asString();if(!approvedPolicies.contains(acceptedPolicy))return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Confirmation(false)),id);long version=((Number)row.get("version")).longValue()+1;Instant now=clock.instant();var retained=(tools.jackson.databind.node.ObjectNode)context.deepCopy();retained.putNull("confirmationToken");db.update("UPDATE experience.newsletter_subscription SET state='ACTIVE',verified_at=?,confirmation_token_hash=NULL,confirmation_expires_at=NULL,encrypted_confirmation_context=?,version=?,updated_at=?,updated_by='newsletter-confirmation' WHERE id=?",stamp(now),secrets.encrypt(id,"CONFIRMATION_CONTEXT",EventCodec.JSON.writeValueAsString(retained)),version,stamp(now),id);db.update("DELETE FROM experience.communication_suppression WHERE destination_hash=? AND channel='EMAIL'",emailHash);consentEvent(id,null,emailHash,"EMAIL","NEWSLETTER",true,acceptedPolicy,"DOUBLE_OPT_IN");consentChanged(id,null,emailHash,"NEWSLETTER",true,version,correlation);audit("public:newsletter",id,correlation,"ACTIVE","EMAIL");return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Confirmation(true)),id);});return EventCodec.JSON.treeToValue(response.body(),Confirmation.class);}
 public Unsubscribed unsubscribe(String token,String key,UUID correlation){readyCrypto();key=ApiValues.idempotencyKey(key);String hash=tokenHash("NEWSLETTER_UNSUBSCRIBE",token);var response=store.executeLocal("public:newsletter","API-101",key,EventCodec.JSON.valueToTree(Map.of("tokenHash",hash)),db->{var found=db.queryForList("SELECT id,email_hash FROM experience.newsletter_subscription WHERE unsubscribe_token_hash=?",hash);if(found.size()!=1)return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Unsubscribed(true)),null);var first=found.getFirst();UUID id=(UUID)first.get("id");String emailHash=(String)first.get("email_hash");lock("email:"+emailHash);var rows=db.queryForList("SELECT id,email_hash,state,version FROM experience.newsletter_subscription WHERE id=? AND unsubscribe_token_hash=? FOR UPDATE",id,hash);if(rows.size()!=1)return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Unsubscribed(true)),id);var row=rows.getFirst();if("UNSUBSCRIBED".equals(row.get("state")))return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Unsubscribed(true)),id);long version=((Number)row.get("version")).longValue()+1;Instant now=clock.instant();db.update("UPDATE experience.newsletter_subscription SET state='UNSUBSCRIBED',confirmation_token_hash=NULL,confirmation_expires_at=NULL,encrypted_confirmation_context=NULL,confirmation_context_expires_at=NULL,version=?,updated_at=?,updated_by='newsletter-unsubscribe' WHERE id=?",version,stamp(now),id);db.update("INSERT INTO experience.communication_suppression(id,created_by,updated_by,email_hash,channel,reason,suppressed_at,destination_hash,destination_kind,hash_key_version) VALUES (?,'public:newsletter','public:newsletter',?,'EMAIL','WITHDRAWN',?,?,'EMAIL',?) ON CONFLICT(destination_hash,channel) DO UPDATE SET reason='WITHDRAWN',suppressed_at=excluded.suppressed_at,version=experience.communication_suppression.version+1,updated_at=excluded.suppressed_at,updated_by='public:newsletter'",EventCodec.uuid7(now),emailHash,stamp(now),emailHash,secrets.hashVersion());consentEvent(id,null,emailHash,"EMAIL","NEWSLETTER",false,policyVersion,"UNSUBSCRIBE");consentChanged(id,null,emailHash,"NEWSLETTER",false,version,correlation);audit("public:newsletter",id,correlation,"UNSUBSCRIBED","EMAIL");return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Unsubscribed(true)),id);});return EventCodec.JSON.treeToValue(response.body(),Unsubscribed.class);}
 public Context context(PrivateWorkload.Proof proof,UUID subscription,UUID job,UUID correlation){readyContext();serviceProof(proof,"API-158");if(job==null||job.equals(new UUID(0,0)))throw ApiValues.invalid();return tx.execute(status->{var rows=jdbc.queryForList("SELECT * FROM experience.newsletter_subscription WHERE id=? FOR UPDATE",subscription);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();String state=(String)row.get("state");if(!Set.of("PENDING","ACTIVE").contains(state))throw PhoneValues.denied();Timestamp contextExpiry=(Timestamp)row.get("confirmation_context_expires_at");if(contextExpiry==null||!contextExpiry.toInstant().isAfter(clock.instant())||row.get("encrypted_confirmation_context")==null)throw new Problem.Failure(ProblemCode.NOT_FOUND);JsonNode cached=EventCodec.JSON.readTree(secrets.decrypt(subscription,"CONFIRMATION_CONTEXT",(byte[])row.get("encrypted_confirmation_context")));String bound=cached.path("jobId").isNull()?null:cached.path("jobId").asString();if(bound!=null&&!bound.equals(job.toString()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);if(bound==null){var next=(tools.jackson.databind.node.ObjectNode)cached.deepCopy();next.put("jobId",job.toString());jdbc.update("UPDATE experience.newsletter_subscription SET encrypted_confirmation_context=?,version=version+1,updated_at=?,updated_by='newsletter-context' WHERE id=?",secrets.encrypt(subscription,"CONFIRMATION_CONTEXT",EventCodec.JSON.writeValueAsString(next)),stamp(clock.instant()),subscription);cached=next;}
  String email=secrets.decrypt(subscription,"EMAIL",(byte[])row.get("email_ciphertext"));if(!secrets.emailHash(email).equals(row.get("email_hash")))throw PhoneValues.denied();String confirm=null;if(state.equals("PENDING")){Timestamp expires=(Timestamp)row.get("confirmation_expires_at");if(expires!=null&&expires.toInstant().isAfter(clock.instant())&&cached.path("confirmationToken").isString())confirm=link("confirm",cached.path("confirmationToken").asString());}String unsubscribe=link("unsubscribe",cached.path("unsubscribeToken").asString());audit.append("service:"+proof.client(),AuditValues.ActorKind.SERVICE,AuditValues.Action.CONSENT_CHANGE,AuditValues.Resource.NOTIFICATION,subscription,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("access","NEWSLETTER_CONTEXT"),null);return new Context(email,confirm,unsubscribe,"TRANSACTIONAL");});}
 /** Bounded TTL cleanup erases expired confirmation capabilities and their recoverable ciphertext. */
 public int expire(int limit){if(limit<1||limit>100)throw ApiValues.invalid();Instant now=clock.instant();return tx.execute(status->{int pending=jdbc.update("WITH due AS (SELECT id FROM experience.newsletter_subscription WHERE state='PENDING' AND confirmation_expires_at<=? ORDER BY confirmation_expires_at,id FOR UPDATE SKIP LOCKED LIMIT ?) UPDATE experience.newsletter_subscription n SET confirmation_token_hash=NULL,confirmation_expires_at=NULL,encrypted_confirmation_context=NULL,confirmation_context_expires_at=NULL,version=n.version+1,updated_at=?,updated_by='newsletter-expiry' FROM due WHERE n.id=due.id",stamp(now),limit,stamp(now));int contexts=jdbc.update("WITH due AS (SELECT id FROM experience.newsletter_subscription WHERE state<>'PENDING' AND confirmation_context_expires_at<=? ORDER BY confirmation_context_expires_at,id FOR UPDATE SKIP LOCKED LIMIT ?) UPDATE experience.newsletter_subscription n SET encrypted_confirmation_context=NULL,confirmation_context_expires_at=NULL,version=n.version+1,updated_at=?,updated_by='newsletter-expiry' FROM due WHERE n.id=due.id",stamp(now),limit,stamp(now));return pending+contexts;});}
 public Consent setEmailConsent(PrivateWorkload.Proof proof,SetConsentInput input,long expected,String key,UUID correlation){var actor=customer(proof,"API-102");if(!"EMAIL".equals(input.channel())||!Set.of("NEWSLETTER","MARKETING","CART_RECOVERY","ORDER_UPDATES").contains(input.purpose())||!approvedPolicies.contains(input.policyVersion()))throw ApiValues.invalid();UUID id=input.destinationId();if(id==null)throw new Problem.Failure(ProblemCode.NOT_FOUND);String requestKey=ApiValues.idempotencyKey(key);var request=EventCodec.JSON.valueToTree(Map.of("destinationId",id,"channel",input.channel(),"purpose",input.purpose(),"granted",input.granted(),"policyVersion",input.policyVersion(),"version",expected));var result=store.executeLocal(actor.party().toString(),"API-102",requestKey,request,db->{var found=db.queryForList("SELECT id,party_id,email_hash,state,version FROM experience.newsletter_subscription WHERE id=? FOR UPDATE",id);if(found.size()!=1||!actor.party().equals(found.getFirst().get("party_id")))throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=found.getFirst();long version=((Number)row.get("version")).longValue();if(version!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!"ACTIVE".equals(row.get("state"))&&input.granted())throw PhoneValues.denied();String hash=(String)row.get("email_hash");lock("email:"+hash);if(input.granted()&&Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.communication_suppression WHERE destination_hash=? AND channel='EMAIL')",Boolean.class,hash)))throw PhoneValues.denied();long next=version+1;Instant now=clock.instant();consentEvent(id,actor.party(),hash,"EMAIL",input.purpose(),input.granted(),input.policyVersion(),"CUSTOMER_API");if(!input.granted())jdbc.update("INSERT INTO experience.communication_suppression(id,created_by,updated_by,email_hash,channel,reason,suppressed_at,destination_hash,destination_kind,hash_key_version) VALUES (?,?,?,?,'EMAIL','WITHDRAWN',?,?,'EMAIL',?) ON CONFLICT(destination_hash,channel) DO NOTHING",EventCodec.uuid7(now),actor.party().toString(),actor.party().toString(),hash,stamp(now),hash,secrets.hashVersion());db.update("UPDATE experience.newsletter_subscription SET version=?,updated_at=?,updated_by=? WHERE id=?",next,stamp(now),actor.party().toString(),id);consentChanged(id,actor.party(),hash,input.purpose(),input.granted(),next,correlation);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.CONSENT_CHANGE,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.SECURITY_POLICY,Map.of("version",version),Map.of("version",next,"channel","EMAIL","state",input.granted()?"ACTIVE":"UNSUBSCRIBED"),null);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Consent("EMAIL",input.purpose(),input.granted(),now)),id);});return EventCodec.JSON.treeToValue(result.body(),Consent.class);}
 public PhoneValues.Eligibility emailEligibility(PrivateWorkload.Proof proof,PhoneValues.EligibilityInput input,UUID correlation){readyCrypto();serviceProof(proof,"API-127");if(!"EMAIL".equals(input.channel()))throw ApiValues.invalid();return tx.execute(status->{String selector;Object selectorValue;if(input.destinationId()!=null){selector="id";selectorValue=input.destinationId();}else if(input.partyId()!=null){selector="party_id";selectorValue=input.partyId();}else{selector="rtrim(email_hash)";selectorValue=input.emailHash().strip();}var rows=jdbc.queryForList("SELECT id,party_id,rtrim(email_hash) AS email_hash,state,version FROM experience.newsletter_subscription WHERE "+selector+"=? ORDER BY id LIMIT 2",selectorValue);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();UUID id=(UUID)row.get("id"),party=(UUID)row.get("party_id");String hash=(String)row.get("email_hash");if(input.partyId()!=null&&!input.partyId().equals(party)||input.emailHash()!=null&&!java.security.MessageDigest.isEqual(hash.getBytes(StandardCharsets.US_ASCII),input.emailHash().strip().getBytes(StandardCharsets.US_ASCII)))throw new Problem.Failure(ProblemCode.NOT_FOUND);lock("email:"+hash);boolean suppressed=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.communication_suppression WHERE destination_hash=? AND channel='EMAIL')",Boolean.class,hash));boolean granted=jdbc.query("SELECT granted FROM experience.consent_event WHERE destination_hash=? AND channel='EMAIL' AND purpose=? ORDER BY occurred_at DESC,created_at DESC,id DESC LIMIT 1",(r,n)->r.getBoolean(1),hash,input.purpose()).stream().findFirst().orElse(false);boolean eligible=!suppressed&&granted;String email=null;if(eligible){email=secrets.decrypt(id,"EMAIL",jdbc.queryForObject("SELECT email_ciphertext FROM experience.newsletter_subscription WHERE id=?",byte[].class,id));if(!secrets.emailHash(email).equals(hash))throw PhoneValues.denied();}audit.append("service:"+proof.client(),AuditValues.ActorKind.SERVICE,AuditValues.Action.CONSENT_CHANGE,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("decision",eligible?"GRANTED":suppressed?"SUPPRESSED":"CONSENT_NOT_GRANTED","channel","EMAIL"),null);return new PhoneValues.Eligibility(eligible,suppressed?"SUPPRESSED":eligible?"GRANTED":"CONSENT_NOT_GRANTED",email,null,hash,policyVersion);});}
 private ActorAssertion.Actor customer(PrivateWorkload.Proof proof,String api){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)&&r.owner().equals("experience")).findFirst().orElseThrow(ActorAssertion::denied);if(proof==null||!route.equals(proof.route())||!"nigson-commerce".equals(proof.client())||proof.actor()==null||!proof.actor().roles().contains("CUSTOMER")||!proof.actor().scopes().contains(route.scope())||proof.actor().organization()!=null)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return proof.actor();}
 private void serviceProof(PrivateWorkload.Proof proof,String api){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)&&r.owner().equals("experience")).findFirst().orElseThrow(ActorAssertion::denied);if(proof==null||!route.equals(proof.route())||!"nigson-integration".equals(proof.client())||proof.actor()!=null||proof.subject()==null||proof.subject().isBlank())throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 private String tokenHash(String purpose,String token){try{return secrets.capabilityHash(purpose,token);}catch(Exception invalid){return "0".repeat(64);}}
 private String link(String action,String token){return publicBase+"/newsletter/"+action+"?token="+URLEncoder.encode(token,StandardCharsets.UTF_8);}
 private void readyCrypto(){if(secrets==null||policyVersion==null||!approvedPolicies.contains(policyVersion))throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);}
 private void readyIntake(){readyCrypto();if(antiSpam==null||publicBase==null||!publicBase.matches("https://[A-Za-z0-9.-]+(?::[0-9]{1,5})?"))throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);}
private void readyContext(){readyCrypto();if(publicBase==null||!publicBase.matches("https://[A-Za-z0-9.-]+(?::[0-9]{1,5})?"))throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);}
}
